}
$p = $req->get_json_params(); if ( ! is_array($p) ) $p = array();
// S278: faktinės porcijos kelias — svorio nereikia.
if ( isset($p['portion_g']) && $p['portion_g'] !== '' && $p['portion_g'] !== null ) {
return new WP_REST_Response(
petshop_fc_portion( isset($p['product_id']) ? (int)$p['product_id'] : 0, (float) $p['portion_g'] ), 200 );
}
/* S286: PRIDEDANT NAUJĄ ĮĖJIMO LAUKĄ — įrašyti IR ČIA. Šis sąrašas
* FIKSUOTAS, tad ko jame nėra, tas calc() nepasiekia. Būtent dėl to
* age_months buvo siunčiamas, bet variklis vis tiek grąžindavo
* AGE_REQUIRED. Ta pati klaidos rūšis kartojosi jau kelis kartus
* (petshop_fc_calc_for_profile $base, petToFormData, sanitize()). */
$in = array(
'product_id'           => isset($p['product_id']) ? (int) $p['product_id'] : 0,
'weight_kg'            => ( isset($p['weight_kg']) && $p['weight_kg'] !== null && $p['weight_kg'] !== '' ) ? (float) $p['weight_kg'] : null,
