'age_months'           => ( isset($p['age_months']) && $p['age_months'] !== null && $p['age_months'] !== '' ) ? (float) $p['age_months'] : null,
'expected_adult_weight_kg' => ( isset($p['expected_adult_weight_kg']) && $p['expected_adult_weight_kg'] !== '' ) ? (float) $p['expected_adult_weight_kg'] : null,
);
return new WP_REST_Response( Petshop_Feeding_Service::calc($in), 200 );
},
));

